"use client";

import { useId, useRef, useState, type ComponentProps, type FormEvent, type ReactNode } from "react";

import { IconAlertCircle, IconSearch } from "@rhs-ui/icons";
import { Button } from "@rhs-ui/primitives/button";
import { Label } from "@rhs-ui/primitives/label";
import { NumberInput } from "@rhs-ui/primitives/number-input";
import { Popover, PopoverContent, PopoverTrigger } from "@rhs-ui/primitives/popover";
import { cn } from "@/lib/utils";
import { daysBetween, parseDay, startOfDay } from "@rhs-ui/marketing/booking-bar/dates";
import { LocationField } from "@rhs-ui/marketing/booking-bar/location-field";
import { RangeCalendar } from "@rhs-ui/marketing/booking-bar/range-calendar";
import type { BookingBarLabels, BookingBarValue, BookingLocation, BookingSearch, DraftRange } from "@rhs-ui/marketing/booking-bar/types";

export type { BookingBarLabels, BookingBarValue, BookingLocation, BookingRange, BookingSearch } from "@rhs-ui/marketing/booking-bar/types";

export interface BookingBarProps extends Omit<ComponentProps<"form">, "onSubmit" | "children" | "defaultValue"> {
  /** Called with the stay and the guests when the reader searches and everything is in order. The bar does no search of its own. */
  onSearch: (search: BookingSearch) => void;
  /** Where the reader can go. The location field comes first when this is set, and is left out when it is not. */
  locations?: readonly BookingLocation[];
  /** The fewest nights a stay can be. 1 by default. A shorter stay is refused in words. */
  minNights?: number;
  /** The most guests, adults and children together. 8 by default. */
  maxGuests?: number;
  /** What the bar starts with. Two adults and no dates by default. */
  defaultValue?: BookingBarValue;
  /** The first day that can be booked, as an ISO date or a Date. Today by default. */
  minDate?: Date | string;
  /** 1 is Monday (the default), 0 is Sunday. */
  weekStartsOn?: 0 | 1;
  /** The language dates and numbers are written in. "en-US" by default. */
  locale?: string;
  /** Which panel starts open. None by default: an open panel takes focus when the page loads, so this is for documentation and screenshots. */
  defaultOpen?: "dates" | "guests";
  /** Words for the fixed text, errors included, for a site that is not in English. */
  labels?: Partial<BookingBarLabels>;
}

const LABELS: BookingBarLabels = {
  search: "Search availability",
  where: "Where to",
  wherePlaceholder: "Choose a destination",
  whereSearch: "Search destinations",
  whereEmpty: "No destination matches that.",
  suggestions: "Destinations",
  selected: "selected",
  dates: "Dates",
  addDates: "Add dates",
  to: "to",
  addCheckOut: "Add check-out",
  checkIn: "Check-in",
  checkOut: "Check-out",
  guests: "Guests",
  adults: "Adults",
  adultsHint: "Ages 13 or above",
  children: "Children",
  childrenHint: "Ages 0 to 12",
  maxGuests: "Up to {max} guests in total.",
  maxReached: "That is the most: {max} guests in total.",
  adultOne: "{count} adult",
  adultOther: "{count} adults",
  childOne: "{count} child",
  childOther: "{count} children",
  nightOne: "{count} night",
  nightOther: "{count} nights",
  submit: "Check availability",
  pickIn: "Choose your check-in date.",
  pickOut: "Now choose your check-out date.",
  minStay: "Minimum stay is {count} nights.",
  chooseDates: "Choose your check-in and check-out dates.",
  stay: "{nights}: {from} to {to}",
  clear: "Clear dates",
  previousMonth: "Previous month",
  nextMonth: "Next month",
};

const text = (template: string, values: Record<string, string | number>) => template.replace(/\{(\w+)\}/g, (marker, key: string) => String(values[key] ?? marker));

/** One part of the bar: a small label over the control, and a soft surface that answers hover, an open panel and the keyboard. */
function Segment({ label, labelId, invalid, className, children }: { label: string; labelId: string; invalid?: boolean; className?: string; children: ReactNode }) {
  return (
    <div className={cn("p-1.5", className)}>
      <div
        role="group"
        aria-labelledby={labelId}
        data-invalid={invalid || undefined}
        className="relative rounded-xl transition-colors duration-150 hover:bg-muted/60 has-[:focus-visible]:ring-[3px] has-[:focus-visible]:ring-ring/40 has-[[data-state=open]]:bg-muted/60 data-[invalid]:ring-1 data-[invalid]:ring-destructive/70 motion-reduce:transition-none"
      >
        <span id={labelId} className="block px-3.5 pt-2.5 text-xs leading-snug font-medium text-muted-foreground">
          {label}
        </span>
        {children}
      </div>
    </div>
  );
}

const TRIGGER = "block w-full min-w-0 rounded-xl px-3.5 pt-0.5 pb-2.5 text-left outline-none";

/**
 * A search bar for anything sold by the night or the day: hotels, holiday homes, venues, car hire. One raised bar
 * with an optional location first, the dates in one picker (check-in and check-out in a two-month calendar with the
 * stay as a band), the guests as two counters in a panel and one button. Once a stay exists the number of nights is
 * said in words, a stay shorter than the minimum is refused in words, in the calendar and under the bar, and a
 * search without dates says so and puts focus on the dates. Every control has a label and works by keyboard. From
 * 768px the parts sit in one row; below it they stack as a form, and the calendar shows one month at a time.
 */
export function BookingBar({ onSearch, locations, minNights = 1, maxGuests = 8, defaultValue, minDate, weekStartsOn = 1, locale = "en-US", defaultOpen, labels: custom, className, ...props }: BookingBarProps) {
  const labels = { ...LABELS, ...custom };
  const id = useId();
  const adultsId = useId();
  const childrenId = useId();
  const problemId = useId();
  const datesRef = useRef<HTMLButtonElement>(null);
  const guestsRef = useRef<HTMLDivElement>(null);

  const limit = Math.max(1, maxGuests);
  const [draft, setDraft] = useState<DraftRange>(() => ({ from: defaultValue?.range ? parseDay(defaultValue.range.from) : null, to: defaultValue?.range ? parseDay(defaultValue.range.to) : null }));
  const startAdults = Math.min(Math.max(1, defaultValue?.adults ?? 2), limit);
  const [adults, setAdults] = useState(startAdults);
  const [kids, setKids] = useState(Math.min(Math.max(0, defaultValue?.children ?? 0), limit - startAdults));
  const [location, setLocation] = useState<string | null>(defaultValue?.location ?? null);
  const [datesOpen, setDatesOpen] = useState(defaultOpen === "dates");
  const [problem, setProblem] = useState<string | null>(null);

  const { from, to } = draft;
  const plural = new Intl.PluralRules(locale);
  const words = (count: number, one: string, other: string) => text(plural.select(count) === "one" ? one : other, { count });
  const nights = from && to ? daysBetween(from, to) : 0;
  // The year is written only when the stay crosses into another one, so an ordinary stay stays short.
  const crosses = from !== null && to !== null && from.getFullYear() !== to.getFullYear();
  const day = new Intl.DateTimeFormat(locale, crosses ? { day: "numeric", month: "short", year: "numeric" } : { day: "numeric", month: "short" });
  const guestText = new Intl.ListFormat(locale, { style: "long", type: "unit" }).format([words(adults, labels.adultOne, labels.adultOther), ...(kids > 0 ? [words(kids, labels.childOne, labels.childOther)] : [])]);
  const reached = adults + kids >= limit;

  function change(next: DraftRange) {
    setDraft(next);
    setProblem(null);
  }

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!from || !to) {
      setProblem(labels.chooseDates);
      datesRef.current?.focus();
      return;
    }
    if (nights < minNights) {
      setProblem(text(labels.minStay, { count: minNights }));
      datesRef.current?.focus();
      return;
    }
    setProblem(null);
    onSearch({ range: { from, to }, nights, adults, children: kids, location: locations ? location : null });
  }

  return (
    <form data-slot="booking-bar" role="search" aria-label={labels.search} noValidate onSubmit={submit} className={cn("@container w-full", className)} {...props}>
      <div
        className={cn(
          "grid divide-y divide-border rounded-2xl border border-border bg-card shadow-sm @3xl:divide-x @3xl:divide-y-0",
          locations ? "@3xl:grid-cols-[minmax(0,1.15fr)_minmax(0,1.45fr)_minmax(0,1fr)_auto]" : "@3xl:grid-cols-[minmax(0,1.45fr)_minmax(0,1fr)_auto]",
        )}
      >
        {locations ? (
          <Segment label={labels.where} labelId={`${id}-where`}>
            <LocationField locations={locations} value={location} onValueChange={setLocation} labels={labels} />
          </Segment>
        ) : null}

        <Segment label={labels.dates} labelId={`${id}-dates`} invalid={problem !== null}>
          <Popover open={datesOpen} onOpenChange={setDatesOpen}>
            <PopoverTrigger ref={datesRef} aria-describedby={problem ? problemId : undefined} className={TRIGGER}>
              <span className="block truncate text-sm leading-snug font-medium">
                {from ? (
                  <>
                    {day.format(from)}
                    {to ? (
                      <>
                        <span className="font-normal text-muted-foreground"> {labels.to} </span>
                        {day.format(to)}
                        <span className="font-normal text-muted-foreground"> · {words(nights, labels.nightOne, labels.nightOther)}</span>
                      </>
                    ) : (
                      <span className="font-normal text-muted-foreground"> · {labels.addCheckOut}</span>
                    )}
                  </>
                ) : (
                  <span className="font-normal text-muted-foreground">{labels.addDates}</span>
                )}
              </span>
            </PopoverTrigger>
            <PopoverContent align="start" collisionPadding={8} aria-label={labels.dates} onOpenAutoFocus={(event) => event.preventDefault()} className="w-auto max-w-[calc(100vw-1rem)] p-0">
              <RangeCalendar
                autoFocus
                value={draft}
                onValueChange={change}
                onComplete={() => setDatesOpen(false)}
                minDate={minDate !== undefined ? parseDay(minDate) : startOfDay(new Date())}
                minNights={minNights}
                locale={locale}
                weekStartsOn={weekStartsOn}
                labels={labels}
              />
            </PopoverContent>
          </Popover>
        </Segment>

        <Segment label={labels.guests} labelId={`${id}-guests`} className="@3xl:border-e-0">
          <Popover defaultOpen={defaultOpen === "guests"}>
            <PopoverTrigger className={TRIGGER}>
              <span className="block truncate text-sm leading-snug font-medium">{guestText}</span>
            </PopoverTrigger>
            {/* Focus goes to the panel, not into a counter: opening it does not select a number the reader did not choose. */}
            <PopoverContent
              ref={guestsRef}
              tabIndex={-1}
              align="start"
              collisionPadding={8}
              aria-label={labels.guests}
              onOpenAutoFocus={(event) => {
                event.preventDefault();
                guestsRef.current?.focus({ preventScroll: true });
              }}
              className="w-[min(21rem,calc(100vw-1rem))] p-5"
            >
              <div className="grid gap-5">
                <div className="flex items-center justify-between gap-4">
                  <div className="min-w-0">
                    <Label htmlFor={adultsId}>{labels.adults}</Label>
                    <p className="mt-1.5 text-xs text-muted-foreground">{labels.adultsHint}</p>
                  </div>
                  <NumberInput id={adultsId} value={adults} onValueChange={setAdults} min={1} max={limit - kids} locale={locale} className="w-32 shrink-0" />
                </div>
                <div className="flex items-center justify-between gap-4">
                  <div className="min-w-0">
                    <Label htmlFor={childrenId}>{labels.children}</Label>
                    <p className="mt-1.5 text-xs text-muted-foreground">{labels.childrenHint}</p>
                  </div>
                  <NumberInput id={childrenId} value={kids} onValueChange={setKids} min={0} max={limit - adults} locale={locale} className="w-32 shrink-0" />
                </div>
                <p aria-live="polite" className={cn("border-t border-border pt-4 text-xs leading-snug", reached ? "font-medium text-foreground" : "text-muted-foreground")}>
                  {text(reached ? labels.maxReached : labels.maxGuests, { max: limit })}
                </p>
              </div>
            </PopoverContent>
          </Popover>
        </Segment>

        <div className="p-3 @3xl:flex @3xl:items-center @3xl:p-2.5">
          <Button type="submit" size="lg" className="h-12 w-full px-6 text-[0.9375rem] @3xl:w-auto">
            <IconSearch />
            {labels.submit}
          </Button>
        </div>
      </div>

      {problem ? (
        <p id={problemId} role="alert" className="mt-3 flex items-start gap-2 px-1 text-sm leading-snug font-medium text-destructive">
          <IconAlertCircle aria-hidden="true" className="mt-0.5 size-4 shrink-0" />
          {problem}
        </p>
      ) : null}
    </form>
  );
}

/**
 * Calendar-day helpers of the booking bar. A day is a Date at midnight in the reader's own time zone, and every sum
 * goes through the year, the month and the day, never through milliseconds, so a change of clock never moves it.
 * They hold no hooks, so a Server Component can use them.
 */

export const startOfDay = (date: Date): Date => new Date(date.getFullYear(), date.getMonth(), date.getDate());
export const addDays = (date: Date, days: number): Date => new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
export const startOfMonth = (date: Date): Date => new Date(date.getFullYear(), date.getMonth(), 1);
/** The same day of another month, or the last day of it when it is shorter: 31 January + 1 month is 28 February. */
export const addMonths = (date: Date, months: number): Date => {
  const first = new Date(date.getFullYear(), date.getMonth() + months, 1);
  return new Date(first.getFullYear(), first.getMonth(), Math.min(date.getDate(), new Date(first.getFullYear(), first.getMonth() + 1, 0).getDate()));
};
export const isSameDay = (a: Date, b: Date): boolean => a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
/** A key for a day, to find its button: "2026-11-18" with the month counted from zero. */
export const dayKey = (date: Date): string => `${date.getFullYear()}-${date.getMonth()}-${date.getDate()}`;
/** How many months a day is from year zero, so two months compare with one number. */
export const monthIndex = (date: Date): number => date.getFullYear() * 12 + date.getMonth();

/** Whole days from one day to another, however many hours a day had on the way (a change of clock has 23 or 25). */
export function daysBetween(from: Date, to: Date): number {
  return Math.round((Date.UTC(to.getFullYear(), to.getMonth(), to.getDate()) - Date.UTC(from.getFullYear(), from.getMonth(), from.getDate())) / 86_400_000);
}

/** A day from a Date, or from text: "2026-12-18" is that calendar day wherever it is read. */
export function parseDay(value: Date | string): Date {
  if (typeof value === "string") {
    const iso = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
    if (iso) return new Date(Number(iso[1]), Number(iso[2]) - 1, Number(iso[3]));
  }
  return startOfDay(new Date(value));
}

/** The weeks of a month, each seven slots long, with null where the week belongs to another month. */
export function monthWeeks(month: Date, weekStartsOn: 0 | 1): (Date | null)[][] {
  const first = startOfMonth(month);
  const lead = (first.getDay() - weekStartsOn + 7) % 7;
  const length = new Date(first.getFullYear(), first.getMonth() + 1, 0).getDate();
  const slots: (Date | null)[] = [...Array.from({ length: lead }, () => null), ...Array.from({ length }, (_, index) => addDays(first, index))];
  while (slots.length % 7 !== 0) slots.push(null);
  return Array.from({ length: slots.length / 7 }, (_, week) => slots.slice(week * 7, week * 7 + 7));
}

"use client";

import { useState } from "react";

import { IconCheck, IconChevronsUpDown } from "@rhs-ui/icons";
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from "@rhs-ui/primitives/command";
import { Popover, PopoverContent, PopoverTrigger } from "@rhs-ui/primitives/popover";
import type { BookingBarLabels, BookingLocation } from "@rhs-ui/marketing/booking-bar/types";

export interface LocationFieldProps {
  /** Where the reader can go. */
  locations: readonly BookingLocation[];
  /** The `value` of the chosen location, or null while none is chosen. */
  value: string | null;
  /** Called with the `value` of the location the reader chooses. */
  onValueChange: (value: string) => void;
  /** The words of the field: its placeholder, the search, the empty list and the names assistive technology reads. */
  labels: BookingBarLabels;
}

/**
 * The location of the booking bar: a trigger that opens a searchable list, with the keyboard of a combobox (type to
 * filter, arrow keys move, Enter chooses, Escape closes and returns focus). It is written out here, on the same
 * popover and command primitives as the Combobox, so that every word it says to assistive technology (the name of the
 * search, of the list and of the chosen option) comes from the bar's labels instead of from English.
 */
export function LocationField({ locations, value, onValueChange, labels }: LocationFieldProps) {
  const [open, setOpen] = useState(false);
  const current = locations.find((location) => location.value === value);

  function choose(next: string) {
    onValueChange(next);
    setOpen(false);
  }

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger
        data-placeholder={current ? undefined : ""}
        className="flex w-full min-w-0 items-center justify-between gap-2 rounded-xl px-3.5 pt-0.5 pb-2.5 text-left text-sm font-medium whitespace-nowrap outline-none data-[placeholder]:font-normal data-[placeholder]:text-muted-foreground"
      >
        <span className="truncate">{current?.label ?? labels.wherePlaceholder}</span>
        <IconChevronsUpDown aria-hidden="true" size={16} className="shrink-0 text-muted-foreground" />
      </PopoverTrigger>
      <PopoverContent align="start" collisionPadding={8} aria-label={labels.where} className="w-(--radix-popover-trigger-width) min-w-56 overflow-hidden p-0">
        <Command loop className="rounded-none bg-transparent">
          <CommandInput placeholder={labels.whereSearch} aria-label={labels.whereSearch} />
          <CommandList label={labels.suggestions}>
            <CommandEmpty>{labels.whereEmpty}</CommandEmpty>
            <CommandGroup>
              {locations.map((location) => {
                const chosen = location.value === value;
                return (
                  <CommandItem key={location.value} value={location.value} keywords={[location.label]} data-checked={chosen || undefined} onSelect={() => choose(location.value)} className="pr-8">
                    <span className="flex min-w-0 flex-col gap-0.5">
                      <span className="truncate text-foreground">{location.label}</span>
                      {location.description ? <span className="text-xs text-muted-foreground">{location.description}</span> : null}
                    </span>
                    {chosen ? (
                      <>
                        <IconCheck aria-hidden="true" size={14} className="absolute right-2" />
                        <span className="sr-only">, {labels.selected}</span>
                      </>
                    ) : null}
                  </CommandItem>
                );
              })}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

"use client";

import { useEffect, useId, useRef, useState, useSyncExternalStore, type FocusEvent, type KeyboardEvent } from "react";

import { IconAlertCircle, IconChevronLeft, IconChevronRight } from "@rhs-ui/icons";
import { Button } from "@rhs-ui/primitives/button";
import { cn } from "@/lib/utils";
import { addDays, addMonths, dayKey, daysBetween, isSameDay, monthIndex, monthWeeks, startOfDay, startOfMonth } from "@rhs-ui/marketing/booking-bar/dates";
import type { BookingBarLabels, DraftRange } from "@rhs-ui/marketing/booking-bar/types";

export interface RangeCalendarProps {
  /** The stay as far as it is chosen. */
  value: DraftRange;
  /** Called with every change: a new check-in, a check-out, or both cleared. */
  onValueChange: (range: DraftRange) => void;
  /** Called once both days are chosen, so the panel around the calendar can close. */
  onComplete: () => void;
  /** The first day that can be chosen, at midnight. */
  minDate: Date;
  /** The fewest nights a stay can be. */
  minNights: number;
  /** The language month and weekday names are written in. */
  locale: string;
  /** 1 is Monday, 0 is Sunday. */
  weekStartsOn: 0 | 1;
  /** The words of the calendar. */
  labels: BookingBarLabels;
  /** Move focus to a day when the calendar mounts, so a keyboard opens it ready to use. */
  autoFocus?: boolean;
  className?: string;
}

const WIDE = "(min-width: 640px)";
const subscribeWide = (notify: () => void): (() => void) => {
  const query = window.matchMedia(WIDE);
  query.addEventListener("change", notify);
  return () => query.removeEventListener("change", notify);
};
const readWide = () => window.matchMedia(WIDE).matches;

const text = (template: string, values: Record<string, string | number>) => template.replace(/\{(\w+)\}/g, (marker, key: string) => String(values[key] ?? marker));

const NAV =
  "grid size-9 place-items-center rounded-md text-muted-foreground outline-none transition-colors duration-150 hover:bg-muted hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/40 disabled:pointer-events-none disabled:opacity-30 motion-reduce:transition-none";

/**
 * A calendar for choosing a stay: check-in and check-out in one picker, two months side by side from 640px and one
 * below. The days between the two are a band, hovering or moving to a day after the check-in previews the stay, days
 * before the first bookable day and days closer to the check-in than the minimum stay cannot be chosen, and trying
 * one says why in words. It is a grid for assistive technology: arrow keys move by day and week, Page Up and Down by
 * month, Home and End to the start and end of the week, Enter chooses. Mount it only while it is shown: it reads the
 * reader's clock.
 */
export function RangeCalendar({ value, onValueChange, onComplete, minDate, minNights, locale, weekStartsOn, labels, autoFocus = false, className }: RangeCalendarProps) {
  const id = useId();
  const root = useRef<HTMLDivElement>(null);
  const wide = useSyncExternalStore(subscribeWide, readWide, () => true);
  const visible = wide ? 2 : 1;
  const today = startOfDay(new Date());
  const { from, to } = value;

  // Open on the check-in, else today, but never before the first bookable day: a picker opens where something can be chosen.
  const [focused, setFocused] = useState(() => {
    const start = startOfDay(from ?? today);
    return start < minDate ? minDate : start;
  });
  const [month, setMonth] = useState(() => startOfMonth(focused));
  const [hover, setHover] = useState<Date | null>(null);
  const [inside, setInside] = useState(false);
  const [problem, setProblem] = useState<string | null>(null);
  // The day to give focus to once the render that shows it is done.
  const toFocus = useRef<string | null>(autoFocus ? dayKey(focused) : null);

  useEffect(() => {
    if (!toFocus.current) return;
    root.current?.querySelector<HTMLElement>(`[data-day="${toFocus.current}"]`)?.focus({ preventScroll: true });
    toFocus.current = null;
  });

  const months = Array.from({ length: visible }, (_, index) => addMonths(startOfMonth(month), index));
  const showing = (date: Date) => monthIndex(date) >= monthIndex(month) && monthIndex(date) < monthIndex(month) + visible;
  // There is always one day in the tab order: the focused one, or the first bookable day of the first month shown.
  const tabKey = dayKey(showing(focused) ? focused : monthIndex(month) === monthIndex(minDate) ? minDate : startOfMonth(month));

  const nightsWords = (count: number) => text(new Intl.PluralRules(locale).select(count) === "one" ? labels.nightOne : labels.nightOther, { count });
  const preview = hover ?? (inside ? focused : null);
  // Only a day that could end the stay previews it: pointing at one that is too close says nothing, and pressing it says why.
  const previewEnd = from && !to && preview && daysBetween(from, preview) >= Math.max(1, minNights) ? preview : null;
  const end = to ?? previewEnd;
  const stay = new Intl.DateTimeFormat(locale, { weekday: "short", day: "numeric", month: "short" });
  const title = new Intl.DateTimeFormat(locale, { month: "long", year: "numeric" });
  const weekday = (date: Date, style: "narrow" | "long") => new Intl.DateTimeFormat(locale, { weekday: style }).format(date);
  const full = new Intl.DateTimeFormat(locale, { weekday: "long", day: "numeric", month: "long", year: "numeric" });

  function moveTo(date: Date) {
    const next = date < minDate ? minDate : date;
    setFocused(next);
    if (monthIndex(next) < monthIndex(month)) setMonth(startOfMonth(next));
    else if (monthIndex(next) >= monthIndex(month) + visible) setMonth(startOfMonth(addMonths(next, 1 - visible)));
    toFocus.current = dayKey(next);
  }

  function pick(day: Date) {
    if (day < minDate) return;
    if (!from || to || day <= from) {
      // A first day, a new first day after a finished stay, or an earlier one: the stay starts over from here.
      setProblem(null);
      onValueChange({ from: day, to: null });
      return;
    }
    if (daysBetween(from, day) < minNights) {
      setProblem(text(labels.minStay, { count: minNights }));
      return;
    }
    setProblem(null);
    onValueChange({ from, to: day });
    onComplete();
  }

  function onKey(event: KeyboardEvent<HTMLButtonElement>, date: Date) {
    const column = (date.getDay() - weekStartsOn + 7) % 7;
    const moves: Record<string, () => Date> = {
      ArrowLeft: () => addDays(date, -1),
      ArrowRight: () => addDays(date, 1),
      ArrowUp: () => addDays(date, -7),
      ArrowDown: () => addDays(date, 7),
      PageUp: () => addMonths(date, event.shiftKey ? -12 : -1),
      PageDown: () => addMonths(date, event.shiftKey ? 12 : 1),
      Home: () => addDays(date, -column),
      End: () => addDays(date, 6 - column),
    };
    const move = moves[event.key];
    if (move) {
      event.preventDefault();
      moveTo(move());
    } else if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      pick(date);
    }
  }

  function leave(event: FocusEvent<HTMLDivElement>) {
    if (!event.currentTarget.contains(event.relatedTarget)) setInside(false);
  }

  const message = to && from ? text(labels.stay, { nights: nightsWords(daysBetween(from, to)), from: stay.format(from), to: stay.format(to) }) : from ? labels.pickOut : labels.pickIn;

  return (
    <div ref={root} data-slot="range-calendar" onMouseLeave={() => setHover(null)} onBlur={leave} className={cn("select-none", className)}>
      {/* A month is 280px wide. On the narrowest phones the sides are 12px instead of 16px, so the month and its panel fit inside a 320px screen with a gutter either side. */}
      <div className="flex justify-center gap-8 p-4 max-[22.5rem]:px-3">
        {months.map((shown, index) => {
          const titleId = `${id}-month-${index}`;
          return (
            <div key={monthIndex(shown)} className="w-full max-w-[17.5rem] min-w-0">
              <div className="relative mb-2 flex h-9 items-center justify-center">
                {index === 0 ? (
                  <button type="button" aria-label={labels.previousMonth} disabled={monthIndex(month) <= monthIndex(minDate)} onClick={() => setMonth(addMonths(month, -1))} className={cn(NAV, "absolute left-0")}>
                    <IconChevronLeft size={16} />
                  </button>
                ) : null}
                <p id={titleId} aria-live="polite" className="text-sm font-medium capitalize">
                  {title.format(shown)}
                </p>
                {index === visible - 1 ? (
                  <button type="button" aria-label={labels.nextMonth} onClick={() => setMonth(addMonths(month, 1))} className={cn(NAV, "absolute right-0")}>
                    <IconChevronRight size={16} />
                  </button>
                ) : null}
              </div>

              <div role="grid" aria-labelledby={titleId}>
                <div role="row" className="grid grid-cols-7">
                  {Array.from({ length: 7 }, (_, column) => {
                    // 1 January 2024 was a Monday.
                    const day = new Date(2024, 0, 1 + ((weekStartsOn + 6 + column) % 7));
                    return (
                      <span key={column} role="columnheader" aria-label={weekday(day, "long")} className="grid h-8 place-items-center text-[0.6875rem] font-medium text-muted-foreground uppercase">
                        {weekday(day, "narrow")}
                      </span>
                    );
                  })}
                </div>
                {monthWeeks(shown, weekStartsOn).map((week) => (
                  <div key={dayKey(week.find((slot) => slot) ?? shown)} role="row" className="grid grid-cols-7">
                    {week.map((day, column) => {
                      if (!day) return <span key={column} role="gridcell" aria-hidden="true" className="h-10" />;
                      const isFrom = from !== null && isSameDay(day, from);
                      const isTo = to !== null && isSameDay(day, to);
                      const isPreview = previewEnd !== null && isSameDay(day, previewEnd);
                      const between = from !== null && end !== null && day > from && day < end;
                      const off = day < minDate;
                      const tooShort = from !== null && !to && day > from && daysBetween(from, day) < minNights;
                      const blocked = off || tooShort;
                      const date = full.format(day);
                      const rowStart = column === 0 || !week[column - 1];
                      const rowEnd = column === 6 || !week[column + 1];
                      return (
                        <span
                          key={dayKey(day)}
                          role="gridcell"
                          aria-selected={isFrom || isTo || between}
                          className={cn(
                            "relative grid h-10 place-items-center",
                            between && cn("bg-muted", rowStart && "rounded-l-lg", rowEnd && "rounded-r-lg"),
                            // The half of the band that joins an end to the days beside it; at the end of a row there is nothing to join.
                            isFrom && end && !rowEnd && "before:absolute before:inset-y-0 before:right-0 before:left-1/2 before:bg-muted",
                            (isTo || isPreview) && from && !rowStart && "before:absolute before:inset-y-0 before:right-1/2 before:left-0 before:bg-muted",
                          )}
                        >
                          <button
                            type="button"
                            data-day={dayKey(day)}
                            tabIndex={dayKey(day) === tabKey ? 0 : -1}
                            aria-disabled={blocked || undefined}
                            aria-current={isSameDay(day, today) ? "date" : undefined}
                            aria-label={isFrom ? `${date}, ${labels.checkIn}` : isTo ? `${date}, ${labels.checkOut}` : date}
                            onClick={() => {
                              setFocused(day);
                              pick(day);
                            }}
                            onKeyDown={(event) => onKey(event, day)}
                            onFocus={() => {
                              setFocused(day);
                              setInside(true);
                            }}
                            onMouseEnter={() => setHover(day)}
                            className={cn(
                              "relative z-10 grid size-10 place-items-center rounded-lg text-sm tabular-nums outline-none transition-colors duration-100 focus-visible:ring-[3px] focus-visible:ring-ring/40 motion-reduce:transition-none",
                              isFrom || isTo ? "bg-foreground text-background" : between ? "hover:bg-foreground/10" : !blocked && "hover:bg-muted",
                              isPreview && "ring-1 ring-foreground/60 ring-inset",
                              isSameDay(day, today) && !isFrom && !isTo && "font-semibold underline decoration-2 underline-offset-4",
                              off && "cursor-not-allowed text-muted-foreground/40 line-through",
                              tooShort && "cursor-not-allowed text-muted-foreground/50",
                            )}
                          >
                            {day.getDate()}
                          </button>
                        </span>
                      );
                    })}
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>

      <div className="flex items-center justify-between gap-4 border-t border-border px-4 py-3">
        <p aria-live="polite" className="min-w-0 text-sm leading-snug text-pretty">
          {problem ? (
            <span className="flex items-start gap-2 font-medium text-destructive">
              <IconAlertCircle aria-hidden="true" className="mt-px size-4 shrink-0" />
              {problem}
            </span>
          ) : (
            <>
              <span className={cn(to ? "font-medium tabular-nums" : "text-foreground")}>{message}</span>
              {from && !to && minNights > 1 ? <span className="text-muted-foreground"> {text(labels.minStay, { count: minNights })}</span> : null}
            </>
          )}
        </p>
        <Button
          type="button"
          variant="ghost"
          size="sm"
          disabled={!from}
          onClick={() => {
            setProblem(null);
            onValueChange({ from: null, to: null });
          }}
          className="shrink-0"
        >
          {labels.clear}
        </Button>
      </div>
    </div>
  );
}

/** A stay: the first night and the day of leaving, both calendar days at midnight in the reader's own time zone. */
export interface BookingRange {
  from: Date;
  to: Date;
}

/** A range that is still being chosen: the check-in is there, the check-out may not be. */
export interface DraftRange {
  from: Date | null;
  to: Date | null;
}

export interface BookingLocation {
  /** What is sent to onSearch: "lisbon". */
  value: string;
  /** What the reader sees: "Lisbon, Portugal". */
  label: string;
  /** A second line under it: "Alfama, Baixa and Chiado". */
  description?: string;
}

export interface BookingSearch {
  /** The check-in day and the check-out day. */
  range: BookingRange;
  /** How many nights that is. */
  nights: number;
  /** How many adults. At least one. */
  adults: number;
  /** How many children. Zero when none. */
  children: number;
  /** The `value` of the chosen location, or null when the bar has none or nothing was chosen. */
  location: string | null;
}

export interface BookingBarValue {
  /** The stay the bar starts with. Days are ISO dates ("2026-12-18") or Dates; text is read as that calendar day, which keeps a Server Component's value from shifting with a time zone. */
  range?: { from: Date | string; to: Date | string } | null;
  /** How many adults. 2 by default. */
  adults?: number;
  /** How many children. 0 by default. */
  children?: number;
  /** The `value` of the chosen location. */
  location?: string | null;
}

export interface BookingBarLabels {
  /** The name of the search for assistive technology. */
  search: string;
  /** The label of the location. */
  where: string;
  /** What the location says while nothing is chosen. */
  wherePlaceholder: string;
  /** The placeholder of the search inside the list of locations, which is also its name for assistive technology. */
  whereSearch: string;
  /** Said when no location matches what was typed. */
  whereEmpty: string;
  /** The name of the list of locations for assistive technology. */
  suggestions: string;
  /** Said by assistive technology after the location that is chosen: "Lisbon, selected". */
  selected: string;
  /** The label of the dates, and the name of the calendar. */
  dates: string;
  /** What the dates say while nothing is chosen. */
  addDates: string;
  /** Between the two days of a stay: "18 Dec to 21 Dec". */
  to: string;
  /** What the dates say after the check-in, while the check-out is still to be chosen. */
  addCheckOut: string;
  /** The name of the check-in day, said by assistive technology and in the calendar. */
  checkIn: string;
  /** The name of the check-out day. It also stands in the dates while only the check-in is chosen. */
  checkOut: string;
  /** The label of the guests, and the name of the panel. */
  guests: string;
  /** The label of the adults counter. */
  adults: string;
  /** Under the adults counter. */
  adultsHint: string;
  /** The label of the children counter. */
  children: string;
  /** Under the children counter. */
  childrenHint: string;
  /** The line under the counters. {max} stands for the most guests. */
  maxGuests: string;
  /** The same line once the most is reached. {max} stands for the most guests. */
  maxReached: string;
  /** One adult. {count} stands for the number. */
  adultOne: string;
  /** Several adults. {count} stands for the number. */
  adultOther: string;
  /** One child. {count} stands for the number. */
  childOne: string;
  /** Several children. {count} stands for the number. */
  childOther: string;
  /** One night. {count} stands for the number. */
  nightOne: string;
  /** Several nights. {count} stands for the number. */
  nightOther: string;
  /** The button. */
  submit: string;
  /** Said in the calendar while nothing is chosen. */
  pickIn: string;
  /** Said in the calendar once the check-in is chosen. */
  pickOut: string;
  /** Said when the stay is shorter than the minimum. {count} stands for the number of nights. */
  minStay: string;
  /** Said under the bar when the reader searches without dates. */
  chooseDates: string;
  /** The calendar's summary of a chosen stay. {nights} stands for "3 nights", {from} and {to} for the days. */
  stay: string;
  /** The button that clears the dates. */
  clear: string;
  /** The name of the button to the month before. */
  previousMonth: string;
  /** The name of the button to the month after. */
  nextMonth: string;
}
